function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 400) return 'grid needs 1 to 400 rows.';
  const n = grid.length;
  let thieves = 0;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square (n rows of n cells).';
    for (const cell of row) {
      if (cell !== 0 && cell !== 1) return 'Every cell is 0 or 1.';
      thieves += cell;
    }
  }
  if (thieves === 0) return 'The grid needs at least one thief (a 1).';
  return null;
}

