function maximumSafenessFactor(grid) {
  const n = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const dist = Array.from({ length: n }, () => new Array(n).fill(-1));
  const queue = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === 1) {
        dist[r][c] = 0;
        queue.push([r, c]);
      }
    }
  }
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] === -1) {
        dist[nr][nc] = dist[r][c] + 1;
        queue.push([nr, nc]);
      }
    }
  }

  function canReach(limit) {
    const visited = Array.from({ length: n }, () => new Array(n).fill(false));
    const frontier = [[0, 0]];
    visited[0][0] = true;
    for (let head = 0; head < frontier.length; head++) {
      const [r, c] = frontier[head];
      if (r === n - 1 && c === n - 1) return true;
      for (const [dr, dc] of directions) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc] && dist[nr][nc] >= limit) {
          visited[nr][nc] = true;
          frontier.push([nr, nc]);
        }
      }
    }
    return false;
  }

  let low = 0;
  let high = Math.min(dist[0][0], dist[n - 1][n - 1]);
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (canReach(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

