function maximumSafenessFactor(grid) {
  // Distances by checking every thief, then a max-min Dijkstra that scans for the best open cell.
  const n = grid.length;
  const thieves = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (grid[r][c] === 1) thieves.push([r, c]);
  const near = (r, c) => Math.min(...thieves.map(([tr, tc]) => Math.abs(tr - r) + Math.abs(tc - c)));
  const best = Array.from({ length: n }, () => new Array(n).fill(-1));
  const done = Array.from({ length: n }, () => new Array(n).fill(false));
  best[0][0] = near(0, 0);
  for (;;) {
    let pick = null;
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
      if (!done[r][c] && best[r][c] >= 0 && (pick === null || best[r][c] > best[pick[0]][pick[1]])) pick = [r, c];
    }
    const [r, c] = pick;
    if (r === n - 1 && c === n - 1) return best[r][c];
    done[r][c] = true;
    for (const [x, y] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (x < 0 || y < 0 || x >= n || y >= n || done[x][y]) continue;
      const value = Math.min(best[r][c], near(x, y));
      if (value > best[x][y]) best[x][y] = value;
    }
  }
}

