function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const style = Math.floor(rand() * 3);
  const grid = Array.from({ length: n }, () => new Array(n).fill(0));
  if (style === 0) {
    // A handful of scattered thieves.
    const count = 1 + Math.floor(rand() * (size === 'large' ? 12 : 3));
    for (let i = 0; i < count; i++) grid[Math.floor(rand() * n)][Math.floor(rand() * n)] = 1;
  } else {
    // Random density, sparse for large grids so long safe corridors exist.
    const density = size === 'large' ? (style === 1 ? 0.002 : 0.02) : rand() * 0.5;
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (rand() < density) grid[r][c] = 1;
  }
  if (!grid.some(row => row.includes(1))) grid[Math.floor(rand() * n)][Math.floor(rand() * n)] = 1;
  return [grid];
}
